/**
 * Mirror a persistent slot's `/state/logs` directory onto the framework store.
 *
 * One loop for every file in the folder. A file whose size and mtime match
 * the last upload is left alone, including the read. Anything else is read
 * from its tail, masked, and written over the same key. Store keys whose
 * files are gone are deleted. The timer lives on the serve process, because
 * a persistent VM stays up between turns. Freeze pods do not enter this path.
 */
import { open, readdir, stat } from "node:fs/promises";
import { join } from "node:path";
import { cursorHostedFiles } from "../files-backends/cursor-hosted.js";
import { agentSdkStorageKeys } from "../storage-protocol.js";
import { resolveApiKeySync } from "./cursor/credentials.js";
import { describeError, describeErrorCode } from "./describe-error.js";
import { maskStartLogTokens, START_LOG_STORE_MAX_BYTES } from "./start-log-store.js";
import { resolveAgentV2Hosting } from "./v2-hosting.js";
/** How often the resident process snapshots the directory. */
export const PERSISTENT_STAGE_LOG_SYNC_INTERVAL_MS = 30_000;
/**
 * Basenames written by the persistent stage logger: timestamp, optional generation, stage.
 * Rejects paths, so a listing cannot escape the directory.
 */
export const PERSISTENT_STAGE_LOG_FILE_NAME = /^[A-Za-z0-9][A-Za-z0-9._-]{0,180}\.log$/;
export function selectPersistentStageLogMirror(input) {
    const hosting = resolveAgentV2Hosting({
        architecture: input.project.agent.architecture,
        env: input.env,
    });
    if (hosting.kind !== "cursor-managed-persistent") {
        return undefined;
    }
    return {
        logsDir: input.logsDir,
        sink: cursorHostedFiles({
            resolveStoreSourceId: () => hosting.resolveStoreIds().frameworkStoreSourceId,
            resolveApiKey: () => resolveApiKeySync()?.apiKey,
        }),
        agentName: input.project.name,
        logger: input.logger ?? (() => { }),
    };
}
/**
 * Start the directory sync and return a stop that flushes once more. The
 * interval does not keep the process alive on its own. A tick that lands
 * while a sync is running is dropped; stop still runs one more after it.
 */
export function startPersistentStageLogMirror(mirror, options) {
    const uploaded = new Map();
    let stopped = false;
    let syncing = false;
    let chain = Promise.resolve();
    const syncOnce = () => {
        chain = chain
            .then(() => syncPersistentStageLogDirectory({
            dir: mirror.logsDir,
            sink: mirror.sink,
            agentName: mirror.agentName,
            uploaded,
            logger: mirror.logger,
        }))
            .catch((error) => {
            mirror.logger(`[bdk] persistent-stage-logs: sync failed (${describeError(error)})`);
        });
        return chain;
    };
    const timer = setInterval(() => {
        if (stopped || syncing) {
            return;
        }
        syncing = true;
        void syncOnce().finally(() => {
            syncing = false;
        });
    }, options?.intervalMs ?? PERSISTENT_STAGE_LOG_SYNC_INTERVAL_MS);
    timer.unref();
    syncing = true;
    void syncOnce().finally(() => {
        syncing = false;
    });
    return {
        stop: () => {
            if (stopped) {
                return chain;
            }
            stopped = true;
            clearInterval(timer);
            return syncOnce();
        },
    };
}
/**
 * Upload changed files under `persistent-stage-logs/`, then drop keys for files that are
 * no longer in the directory. A missing directory is a no-op, so a tick before
 * the first stage command does not sweep a previous snapshot.
 */
export async function syncPersistentStageLogDirectory(args) {
    const logger = args.logger ?? (() => { });
    const maxBytes = args.maxBytes ?? START_LOG_STORE_MAX_BYTES;
    let entries;
    try {
        entries = await readdir(args.dir, { withFileTypes: true });
    }
    catch (error) {
        if (isEnoent(error)) {
            return;
        }
        logger(`[bdk] persistent-stage-logs: read dir failed (${describeError(error)})`);
        return;
    }
    const desired = new Set();
    const names = entries
        .filter((entry) => entry.isFile() && PERSISTENT_STAGE_LOG_FILE_NAME.test(entry.name))
        .map((entry) => entry.name)
        .sort();
    for (const name of names) {
        const path = join(args.dir, name);
        let fileStat;
        try {
            fileStat = await stat(path);
        }
        catch (error) {
            if (isEnoent(error)) {
                continue;
            }
            // Keep the previous snapshot when this tick cannot see the file.
            logger(`[bdk] persistent-stage-logs: read failed for ${name} (${describeError(error)})`);
            desired.add(name);
            continue;
        }
        if (fileStat.size === 0) {
            continue;
        }
        const previous = args.uploaded.get(name);
        if (previous?.size === fileStat.size && previous.mtimeMs === fileStat.mtimeMs) {
            desired.add(name);
            continue;
        }
        let raw;
        try {
            raw = await readLogTail(path, fileStat.size, maxBytes);
        }
        catch (error) {
            if (isEnoent(error)) {
                continue;
            }
            logger(`[bdk] persistent-stage-logs: read failed for ${name} (${describeError(error)})`);
            desired.add(name);
            continue;
        }
        if (raw.length === 0) {
            desired.add(name);
            continue;
        }
        const body = maskStartLogTokens(raw);
        desired.add(name);
        const key = agentSdkStorageKeys.persistentStageLog(args.agentName, name);
        try {
            await args.sink.put(key, new TextEncoder().encode(body));
            args.uploaded.set(name, { size: fileStat.size, mtimeMs: fileStat.mtimeMs });
        }
        catch (error) {
            logger(`[bdk] persistent-stage-logs: persist failed for ${name} (${describeError(error)})`);
        }
    }
    const prefix = agentSdkStorageKeys.persistentStageLogsPrefix(args.agentName);
    let listed;
    try {
        listed = await args.sink.list(prefix);
    }
    catch (error) {
        logger(`[bdk] persistent-stage-logs: list failed (${describeError(error)})`);
        return;
    }
    for (const item of listed) {
        const name = fileNameFromPersistentStageLogKey(item.key, prefix);
        if (name === undefined || desired.has(name)) {
            continue;
        }
        try {
            await args.sink.delete(item.key);
            args.uploaded.delete(name);
        }
        catch (error) {
            logger(`[bdk] persistent-stage-logs: delete failed for ${name} (${describeError(error)})`);
        }
    }
}
/** Read the last `maxBytes` of a file without loading the rest of it. */
async function readLogTail(path, size, maxBytes) {
    const length = Math.min(size, maxBytes);
    const position = size - length;
    const handle = await open(path, "r");
    try {
        const buffer = Buffer.alloc(length);
        let offset = 0;
        while (offset < length) {
            const { bytesRead } = await handle.read(buffer, offset, length - offset, position + offset);
            if (bytesRead === 0) {
                break;
            }
            offset += bytesRead;
        }
        return new TextDecoder().decode(buffer.subarray(0, offset));
    }
    finally {
        await handle.close();
    }
}
function fileNameFromPersistentStageLogKey(key, prefix) {
    if (!key.startsWith(prefix)) {
        return undefined;
    }
    const segment = key.slice(prefix.length);
    if (segment.length === 0 || segment.includes("/")) {
        return undefined;
    }
    try {
        const name = decodeURIComponent(segment);
        return PERSISTENT_STAGE_LOG_FILE_NAME.test(name) ? name : undefined;
    }
    catch {
        return undefined;
    }
}
function isEnoent(error) {
    return describeErrorCode(error) === "ENOENT";
}
